# 第 251-275 课内容数据
LESSONS_PART = [

# ============ 第15章 寻路与导航 (251-265) ============
{"num":251,"title":"寻路与导航入门","summary":"认识 Unity 寻路系统：NavMesh 导航网格、Agent 代理、核心概念与流程。","keywords":"寻路,navmesh,导航,agent,导航网格,入门","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解寻路原理","认识 NavMesh","掌握导航流程"],
 "intro":"“敌人怎么绕墙找到我”靠寻路。本课建立 NavMesh 寻路系统的整体认知。",
 "sections":[
  {"h":"寻路原理","lead":"A* 与导航网格。",
   "steps":["【寻路问题】从 A 点到 B 点怎么走最合理（绕障碍、走最短）。","【经典算法】A* 算法：在“可走区域”上搜索最优路径。","【Unity 方案】NavMesh（导航网格）：把场景“可走区域”预计算成网格，寻路在网格上进行。","【NavMesh】蓝色半透明网格：覆盖地面、斜坡等可走区域；墙洞等不可走区域自动空出。","【寻路流程】1. 烘焙 NavMesh → 2. Agent 设目标 → 3. 自动算出路径并移动。","【NavMeshAgent】挂在角色上的“导航代理”：负责沿路径移动、避障。","【优点】自动绕障、平滑移动、效率高（预计算）。","【适用】敌人 AI、NPC、玩家自动寻路。","【注意】NavMesh 是“静态预烘焙”的；动态障碍用 NavMeshObstacle（第 254 课）。","【完成】理解寻路“地图”思维。"],
   "tips":[{"t":"note","c":"寻路 = 预烘焙“路网”（NavMesh）+ 代理“认路”（Agent）。两步走。"}]},
  {"h":"导航系统组件","lead":"三个角色。",
   "steps":["【NavMeshSurface】烘焙“路网”的组件（挂在场景里，负责 Bake）。","新版寻路包：Window → Package Manager 搜 AI Navigation 安装。","【NavMeshAgent】“走路的人”：挂角色上，SetDestination 指路。","【NavMeshObstacle】“会动的障碍”：挂移动的障碍物（门、箱子），挡路。","【OffMeshLink】“特殊连接”：跳跃点、楼梯（第 255-256 课）。","【流程】搭场景 → 加 NavMeshSurface → Bake → 角色加 Agent → SetDestination。","【查看】Scene 视图看到蓝色网格即烘焙成功。","【版本】Unity 6 用 AI Navigation 包（新版）；旧版 Window → AI → Navigation。","【注意】Agent 必须在网格范围内才能寻路。","【完成】导航系统“三件套”认识完毕。","【下一步】逐个深挖（第 252-256 课）。"],
   "tips":[{"t":"success","c":"导航三件套：Surface（路网）、Agent（走路）、Obstacle（障碍）。组合即寻路系统。"}]},
 ],
 "errors":[{"err":"找不到 Navigation 窗口？","why":"新版用 AI Navigation 包","fix":"Package Manager 安装 AI Navigation，然后 Window → AI → Navigation。"}],
 "exercise":["安装 AI Navigation 包","认识三个核心组件","理解寻路流程"],
 "summary":"寻路入门完成。下一课深挖 NavMeshAgent。"},

{"num":252,"title":"NavMeshAgent 详解","summary":"掌握 NavMeshAgent：移动、速度、避障、停止条件、状态判断。","keywords":"navmeshagent,代理,移动,避障,stoppingdistance,状态","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 Agent 属性","掌握移动控制","掌握状态判断"],
 "intro":"NavMeshAgent 是“会走路的代理”。本课把它从上到下讲透。",
 "sections":[
  {"h":"Agent 核心属性","lead":"走路“配置”。",
   "steps":["【添加】角色加 NavMeshAgent 组件。","【属性】","Speed：移动速度。","Angular Speed：转身速度。","Acceleration：加速。","Stopping Distance：到达目标后停下的距离（攻击距离用）。","Auto Braking：自动刹车（靠近减速）。","Radius / Height：代理体积（碰撞用）。","【移动】agent.SetDestination(target.position); // 每帧或目标变化时设置","【清除】agent.ResetPath(); // 停止当前路径","【停走】agent.isStopped = true/false;","【避开】agent.avoidancePriority 避障优先级（数字小优先）。","【注意】Agent 移动由它自己控制，别同时改 transform 位置（会冲突）。","【完成】Agent 能“走”了！"],
   "tips":[{"t":"note","c":"Agent 四调节：Speed 速度、StoppingDistance 停距、Radius 体积、AngularSpeed 转向。"}]},
  {"h":"状态与路径判断","lead":"agent 现在在干嘛。",
   "steps":["【到达判断】agent.remainingDistance <= agent.stoppingDistance 且 !agent.pathPending 视为到达。","【示例】敌人到达攻击距离才攻击：","if (agent.remainingDistance <= agent.stoppingDistance && !agent.pathPending) { Attack(); }","【是否在走】agent.velocity.magnitude > 0.1f 驱动走路动画（第 229 课）。","【路径状态】agent.pathStatus：PathComplete（到达）、PathInvalid（无效）。","【路径待定】agent.pathPending：正在计算路径（刚设目标时短暂 true）。","【计算失败】目标不可达：agent.hasPath = false；检测用 agent.pathStatus。","【自定义目标】SetDestination 每帧调用没问题（内部去重）。","【演示】给角色设一个目标点，观察 remainingDistance 变化。","【注意】刚设目标的一两帧 remainingDistance 可能不准（等 pathPending 结束）。","【完成】Agent 状态“看得懂”了！"],
   "tips":[{"t":"success","c":"Agent 三问：到没到（remainingDistance）、走没走（velocity）、行不行（pathStatus）。"}]},
 ],
 "errors":[{"err":"Agent 不动？","why":"没设目标、或不在网格、或 isStopped","fix":"确认 SetDestination 被调用且目标可达；Agent 在 NavMesh 上；isStopped=false。"}],
 "exercise":["调 Agent 速度/停距/半径","实现到达判定","用 velocity 驱动动画"],
 "summary":"NavMeshAgent 已掌握。下一课学 NavMesh 烘焙设置。"},

{"num":253,"title":"NavMesh 烘焙设置","summary":"掌握 NavMesh 烘焙：区域划分、Agent 尺寸、可走区域、烘焙参数。","keywords":"navmesh烘焙,bake,区域,agent size,可走区域,参数","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握烘焙参数","掌握区域划分","掌握走坡走台阶"],
 "intro":"NavMesh“怎么烤”决定 AI 能不能走、怎么走。本课掌握烘焙设置。",
 "sections":[
  {"h":"烘焙流程与参数","lead":"Surface + Bake。",
   "steps":["【NavMeshSurface】给场景空对象加 NavMeshSurface 组件（AI Navigation 包）。","【Collect Objects】收集范围：All Game Objects（全场景）/ 指定层。","【Include Layers】包含哪些层（地面层等）。","【Use Geometry】用哪种几何：Physics Colliders（推荐，用碰撞体）或 Render Meshes。","【Agent Type】代理类型（Humanoid/Vehicle 等，可自定义）。","【Agent Radius】代理半径：决定“窄缝能不能过”（半径大过不去窄通道）。","【Agent Height】代理高度：决定“矮洞能不能钻”。","【Max Slope】最大坡度：超过则不可走（台阶 45°）。","【Step Height】台阶高度：能迈上的台阶高度。","【Bake】点 Bake 生成网格。","【注意】改参数后重新 Bake（网格不会自动更新）。","【完成】烘焙“会调”了！"],
   "tips":[{"t":"note","c":"烘焙四关键：Radius（缝宽）、Height（洞高）、MaxSlope（坡度）、StepHeight（台阶）。"}]},
  {"h":"区域与成本","lead":"让 AI“挑路”。",
   "steps":["【Area 区域】给导航网格标区域（Walkable 可走、Not Walkable 不可走、自定义）。","【设置区域】选中物体 → Navigation Area 下拉选择区域。","【成本 Cost】每个区域有成本（Cost）：AI 选路时算“总成本”，成本高的区域尽量避开。","【示例】泥地成本 5、大路成本 1：AI 优先走大路。","【设置成本】Navigation 窗口 → Areas 页签调各区域 Cost。","【不可走区域】把危险区/深水设为 Not Walkable，AI 不会走。","【修改】改区域/成本后重新 Bake。","【应用】AI 避开泥沼、走桥梁。","【注意】区域是“路网属性”，跟物体绑定（Bake 时读）。","【完成】AI 会“挑路”了！","【进阶】动态改区域成本（封路效果，进阶）。"],
   "tips":[{"t":"success","c":"区域成本 = “路况”：成本高 AI 绕开。调成本=调 AI 路线。"}]},
 ],
 "errors":[{"err":"Bake 出来网格不完整？","why":"物体没碰撞体或收集范围不对","fix":"确认地面有 Collider；Collect Objects=All；Use Geometry 用 Colliders；改 Agent 参数。"}],
 "exercise":["调 Radius/Height/MaxSlope 重烘焙","设置泥地高成本区","观察 AI 路线变化"],
 "summary":"烘焙设置已掌握。下一课学动态障碍。"},

{"num":254,"title":"动态障碍 NavMeshObstacle","summary":"用 NavMeshObstacle 做动态障碍：移动的门、掉落的箱子挡路，AI 绕行。","keywords":"动态障碍,navmeshobstacle,障碍物,绕行,移动的门,挡路","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解动态障碍","实现移动障碍挡路","实现开关门挡路"],
 "intro":"“门一关敌人就过不去”——动态障碍让 AI“识别会变的路”。本课实现。",
 "sections":[
  {"h":"NavMeshObstacle 基础","lead":"会动的“路障”。",
   "steps":["【问题】NavMesh 是静态的；移动的物体不在网格里，AI 不知道绕。","【NavMeshObstacle】动态障碍组件：运行时把“挡路区域”标出，AI 自动绕行。","【添加】给移动的障碍物（门、箱子、滚石）加 NavMeshObstacle 组件。","【属性】","Shape：Box（盒子）/ Capsule（胶囊）。","Center / Size：障碍体积。","Carve：勾选后“雕刻”出障碍区域（AI 绕行）；不勾只是碰撞阻挡。","【说明】Carve 开启时，AI 的路径实时更新绕开它。","【性能】Carve 每帧更新有开销，数量别太多。","【完成】移动障碍“挡得住”了！"],
   "tips":[{"t":"note","c":"NavMeshObstacle = 会动的路障：勾 Carve 让 AI 实时绕行。移动障碍必备。"}]},
  {"h":"实战：开关门挡路","lead":"门关 AI 绕行、门开 AI 直走。",
   "steps":["【开门场景】门对象（带 NavMeshObstacle + Carve）。","【状态】门开时：NavMeshObstacle.enabled = false（不挡）；门关时 enabled = true（挡）。","【代码】","public NavMeshObstacle doorObstacle;","void Open() { doorObstacle.enabled = false; /* 门动画 */ }","void Close() { doorObstacle.enabled = true; }","【效果】门关 AI 绕行、门开 AI 穿过。","【性能】很多 Carve 障碍会卡：控制数量或用“区域成本”方案替代（第 253 课）。","【替代方案】动态改区域成本封路（进阶）。","【测试】放一个移动箱子，AI 绕开它。","【完成】动态障碍系统“活”了！","【注意】Carve 障碍要放在 NavMesh 附近才生效。","【说明】物体不动时别开 Carve（省性能）。"],
   "tips":[{"t":"success","c":"动态障碍用法：移动物加 Carve，静止时关掉（省性能）。开关门是经典应用。"}]},
 ],
 "errors":[{"err":"AI 无视障碍直接穿？","why":"没勾 Carve 或障碍不在路径上","fix":"障碍勾 Carve；确认障碍体积覆盖挡住的位置；重新检查烘焙。"}],
 "exercise":["给移动箱子加障碍并测试绕行","做关门挡路、开门放行","控制 Carve 性能"],
 "summary":"动态障碍已掌握。下一课学 NavMesh Link。"},

{"num":255,"title":"Off-Mesh Link 跳跃连接","summary":"用 OffMeshLink 连接 NavMesh 分离区域：跳跃、跨沟、上下楼梯。","keywords":"offmeshlink,跳跃连接,跨区域,自定义连接,navmesh link","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 OffMeshLink","创建跳跃连接","实现跨区移动"],
 "intro":"“跳下悬崖”“跨过沟”——NavMesh 断开处用 OffMeshLink 手动“搭桥”。本课实现。",
 "sections":[
  {"h":"OffMeshLink 概念","lead":"两个点“搭桥”。",
   "steps":["【问题】台阶/沟壑/断桥让 NavMesh 不连续，AI 走不过去。","【OffMeshLink】在两个 NavMesh 区域间手动建立“连接”：AI 走到起点自动“跳”到终点。","【创建】空对象加 OffMeshLink 组件，设 Start/End 两个 Transform 端点。","【端点】起点放 NavMesh 边缘，终点放另一块 NavMesh 边缘。","【激活】两个端点必须是 NavMesh 上的可走位置（否则连接无效）。","【双向】Bidirectional 勾选=可来回走（默认）。","【自动跳】AI 走到起点自动“瞬移/飞”到终点。","【效果】跨沟、下坡、楼梯都能走。","【完成】“搭桥”成功！"],
   "tips":[{"t":"note","c":"OffMeshLink = 手动搭桥：两个端点一接，AI 自动“过桥”。NavMesh 断裂处必备。"}]},
  {"h":"跳跃动画与实现","lead":"让“跳”像样。",
   "steps":["【基础】默认 OffMeshLink 跨越是“瞬间移动”（可选抛物线 Auto）。","【动画】给 Agent 检测“正在过桥”：","在 OnNavMesh 相关回调或判断：","agent.isOnOffMeshLink 为 true 时正处桥（跨接中）。","【示例】过桥时播跳跃动画：","void Update() {","if (agent.isOnOffMeshLink) {","// 播放跳跃动画","anim.SetTrigger(\"Jump\");","// 完成后让 agent 完成跨越","agent.CompleteOffMeshLink();","}","}","【进阶】自定义跨越轨迹（协程控制速度抛弧线，进阶）。","【其他连接】楼梯：用 OffMeshLink 或让楼梯本身可走（Max Slope/Step Height 覆盖）。","【测试】AI 从平台 A 跳/走到平台 B。","【注意】端点要对准 NavMesh 边缘，别悬空。","【完成】AI 能“跨”了！"],
   "tips":[{"t":"success","c":"OffMeshLink 用法 = 两个端点 + isOnOffMeshLink 检测（播动画）+ CompleteOffMeshLink。三步。"}]},
 ],
 "errors":[{"err":"AI 不走上桥？","why":"端点不在 NavMesh 上或没连接上","fix":"把 Start/End 放到 NavMesh 边缘可走位置；确认连接是双向；重建网格。"}],
 "exercise":["搭一个跨沟 OffMeshLink","过桥时播跳跃动画","做楼梯连接"],
 "summary":"OffMeshLink 已掌握。下一课做巡逻路径系统。"},

{"num":256,"title":"AI 巡逻路径系统（Waypoint）","summary":"实现 AI 巡逻：路径点列表、按序巡逻、停留、随机巡逻。","keywords":"巡逻,waypoint,路径点,ai巡逻,巡逻路线,停留","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现路径点巡逻","实现巡逻停留","实现随机巡逻"],
 "intro":"“守卫来回巡逻”是 AI 常态。本课用 Waypoint（路径点）实现多种巡逻方式。",
 "sections":[
  {"h":"路径点巡逻","lead":"按点走、到点停。",
   "steps":["【方式1 手动路径点】场景里放几个空对象作路径点（Waypoint1/2/3）。","【巡逻脚本】","public Transform[] waypoints;","public float speed = 3f;","public float waitTime = 1f;","private NavMeshAgent agent;","private int current = 0;","void Start() { agent = GetComponent<NavMeshAgent>(); GoNext(); }","void GoNext() { agent.SetDestination(waypoints[current].position); }","void Update() {","if (!agent.pathPending && agent.remainingDistance < 1f) {","current = (current + 1) % waypoints.Length;","StartCoroutine(WaitAndGo());","}","}","IEnumerator WaitAndGo() {","agent.isStopped = true;","yield return new WaitForSeconds(waitTime);","agent.isStopped = false;","GoNext();","}","【说明】到点停 waitTime 再去下一个（循环）。","【可视化】路径点可加 Gizmo 画出连线（进阶）。","【测试】AI 沿路径点循环巡逻。","【完成】“巡逻路线”通了！"],
   "tips":[{"t":"note","c":"Waypoint 巡逻 = 路径点数组 + 按序 SetDestination + 到点停留。循环走。"}]},
  {"h":"随机与条件巡逻","lead":"更多巡逻花样。",
   "steps":["【随机巡逻】从路径点随机选下一个：","int next = Random.Range(0, waypoints.Length);","【或】在 NavMesh 上随机找可走点：","RandomPointOnNavMesh(origin, range, out pos);","【实现】RandomPointOnNavMesh 用 NavMesh.SamplePosition：","public static bool RandomPoint(Vector3 center, float range, out Vector3 result) {","for (int i = 0; i < 30; i++) {","Vector3 random = center + Random.insideUnitSphere * range;","NavMeshHit hit;","if (NavMesh.SamplePosition(random, out hit, 1f, NavMesh.AllAreas)) { result = hit.position; return true; }","}","result = Vector3.zero; return false;","}","【视野切换】巡逻与追击结合（第 211/235 课）：","发现玩家 → SetDestination(player)（追）；丢失 → 回巡逻。","【巡逻点绑定敌人】每个敌人自己的路径点数组（可配置）。","【测试】随机巡逻、发现玩家追击、丢失回巡逻。","【完成】AI 巡逻“专业”了！"],
   "tips":[{"t":"success","c":"巡逻三式：固定路线（Waypoint 循环）、随机点（SamplePosition）、条件切换（视野追/巡）。"}]},
 ],
 "errors":[{"err":"AI 巡逻时卡在某点？","why":"路径点不可达或判断条件不满足","fix":"确认路径点在 NavMesh 上可达；remainingDistance 阈值合适；isStopped 正确恢复。"}],
 "exercise":["做固定路线巡逻","做随机点巡逻","整合巡逻与追击"],
 "summary":"巡逻系统完成。下一课做群组 AI。"},

{"num":257,"title":"群组 AI 与避让","summary":"实现多个 AI 协作：互相避让、队形、目标分配，让一群 AI“不打架”。","keywords":"群组ai,避让,队形,目标分配,协作,多agent","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现互相避让","实现目标分配","实现队形"],
 "intro":"“一群敌人一起追你”——多个 Agent 要互相避让、目标分配。本课让 AI“成群”。",
 "sections":[
  {"h":"Agent 互相避让","lead":"不“叠罗汉”。",
   "steps":["【默认避让】NavMeshAgent 自带避让：多个 agent 接近时自动绕开（基于 avoidancePriority 与半径）。","【属性】Agent 的 Radius 影响避让距离；Avoidance Priority 越小越优先（别人让 TA）。","【效果】两个 Agent 相向而行会互相让路。","【说明】避让是局部行为（本地决策），不与寻路冲突。","【调优】Radius 大→让得早但可能“堵路”；调整速度/优先级让队伍顺。","【观察】放 5 个 Agent 一起追目标，看避让是否自然。","【注意】避让不是万能的：狭窄通道会拥堵（用 RVO 或加大间隔，进阶）。","【完成】AI 会“让路”了！"],
   "tips":[{"t":"note","c":"Agent 避让自带：Radius 定“让多早”、Priority 定“谁优先”。放一群就自动排队。"}]},
  {"h":"目标分配与队形","lead":"分工与合作。",
   "steps":["【目标分配】一群敌人不都追同一个点（会挤）：","给每个敌人偏移目标：","Vector3 offset = Random.insideUnitCircle * 2f;","agent.SetDestination(player.position + new Vector3(offset.x, 0, offset.y));","【按队列分配】玩家有几个队友，各分配一个（寻最近的）。","【队形】跟随者保持相对偏移（围绕队长）：","agent.SetDestination(leader.position + formationOffset);","【实现】给每个成员设自己的 formationOffset（菱形/直线/包围）。","【包围圈】敌人散开包围玩家（进阶：占位点系统）。","【简单可用】随机偏移 + 队形偏移即可做出“成群的 AI”。","【测试】5 个敌人不挤在一起、有散开感。","【完成】AI“成群结队”了！","【注意】目标偏移别太大（否则“不追玩家”的错觉）。"],
   "tips":[{"t":"success","c":"群组 AI = 默认避让 + 目标偏移（散开）+ 队形偏移（合作）。组合成“军团”。"}]},
 ],
 "errors":[{"err":"AI 挤成一团？","why":"没偏移或避让半径太小","fix":"给目标加随机偏移；调大 Agent Radius；检查避让优先级。"}],
 "exercise":["观察多个 Agent 自动避让","给敌人目标加偏移散开","实现跟随队形"],
 "summary":"群组 AI 完成。下一课整合导航与动画。"},

{"num":258,"title":"导航与动画整合","summary":"让 AI 的寻路速度驱动动画：走/跑/停切换，攻击时停下，战斗动画。","keywords":"导航动画,整合,速度驱动,走跑停,战斗动画","time":"约 14 分钟","difficulty":"入门",
 "objectives":["整合速度动画","实现攻击停顿","实现战斗状态"],
 "intro":"“AI 走路时有走路动画、停下攻击”——把导航与动画状态机打通。本课整合。",
 "sections":[
  {"h":"速度驱动动画","lead":"走/跑/停自动切换。",
   "steps":["【准备】敌人 Animator（第 130 课）状态：Idle、Walk、Run、Attack、Death。","【参数】Speed（Float）。","【代码】","public NavMeshAgent agent; public Animator anim;","void Update() {","float speed = agent.velocity.magnitude;","anim.SetFloat(\"Speed\", speed, 0.1f, Time.deltaTime);","}","【效果】agent 走→Walk 动画；停→Idle。","【阈值】Blend Tree 把 Idle(0)/Walk(1)/Run(2) 按速度融合（第 134 课）。","【朝向】agent 转向由它自己处理（Angular Speed），动画跟朝向即可。","【到达停顿】agent 停在攻击距离时自动转 Idle（速度 0）。","【测试】敌人走近/停下，动画跟着切换。","【完成】AI“会表演”了！"],
   "tips":[{"t":"note","c":"导航动画 = agent.velocity 大小 → SetFloat(Speed) → 混合树。一行打通。"}]},
  {"h":"攻击与战斗状态","lead":"打到你了。",
   "steps":["【攻击触发】到达攻击距离：","void Update() {","if (agent.remainingDistance <= agent.stoppingDistance && !agent.pathPending) {","Attack();","}","}","void Attack() {","agent.isStopped = true; // 停下","anim.SetTrigger(\"Attack\");","// 攻击动画事件里判定伤害（第 135/240 课）","}","【恢复追击】攻击结束（动画事件/协程）后：","agent.isStopped = false;","agent.SetDestination(player.position);","【攻击冷却】定时攻击（别连发）：","public float attackCooldown = 1.5f;","private float lastAttack;","if (Time.time - lastAttack > attackCooldown) { lastAttack = Time.time; Attack(); }","【死亡】hp<=0：anim.SetTrigger(\"Death\") + 停 agent + 布娃娃（第 242 课）。","【完整循环】追击（走）→ 停下（攻）→ 追击…","【测试】敌人追、停、攻击、死亡全流程动画正确。","【完成】敌人“有血有肉”了！"],
   "tips":[{"t":"success","c":"战斗循环 = 追击（SetDestination）→ 停下（isStopped）→ 攻击（Trigger+冷却）→ 恢复。四步。"}]},
 ],
 "errors":[{"err":"攻击时角色还在走？","why":"没停 agent 或没设 StoppingDistance","fix":"攻击时 agent.isStopped=true；Agent 的 StoppingDistance 设成攻击距离。"}],
 "exercise":["用速度驱动敌人走/停动画","实现攻击停顿与冷却","整合死亡动画"],
 "summary":"导航动画整合完成。下一课做玩家跟随。"},

{"num":259,"title":"玩家跟随与 AI 伙伴","summary":"实现 AI 伙伴：跟随玩家、保持距离、避让、简单协作（攻击同一目标）。","keywords":"玩家跟随,ai伙伴,保持距离,协作,队友,npc跟随","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现跟随玩家","实现保持距离","实现协作攻击"],
 "intro":"“带个小弟”——AI 伙伴跟随、保持距离、帮忙打怪。本课实现。",
 "sections":[
  {"h":"跟随玩家","lead":"小弟“跟班”。",
   "steps":["【脚本 Follower】","public Transform leader; // 玩家","public float followDistance = 2f;","public float stopDistance = 1.5f;","private NavMeshAgent agent;","void Start() { agent = GetComponent<NavMeshAgent>(); }","void Update() {","float dist = Vector3.Distance(transform.position, leader.position);","if (dist > stopDistance) {","// 在玩家身后找目标点（保持跟随距离）","Vector3 toLeader = (transform.position - leader.position).normalized;","Vector3 target = leader.position + toLeader * followDistance;","agent.SetDestination(target);","} else {","agent.isStopped = true;","}","}","【说明】目标点 = 玩家位置 + 指向自己的方向×跟随距离（站在身后）。","【距离】玩家走远就追、近了就停。","【避让】agent 自动避让玩家与障碍。","【测试】玩家移动，伙伴跟随保持距离。","【完成】“跟班”上线！"],
   "tips":[{"t":"note","c":"跟随 = 目标点 = 玩家 + 反方向偏移×距离。三行实现“站身后”。"}]},
  {"h":"协作攻击","lead":"帮你“打怪”。",
   "steps":["【目标识别】伙伴发现敌人：","public float detectRange = 8f;","Enemy FindTarget() {","// 找最近的敌人（Physics.OverlapSphere + 距离比较）","}","【攻击】发现敌人 → 追击 → 攻击（第 258 课敌人逻辑复用）。","【协作】多个伙伴打同一目标（各自攻击，目标共享）。","【切换】目标死亡后重新找。","【实现】复用“敌人 AI”逻辑给伙伴（加“跟随/攻击”状态）。","【状态机】伙伴状态：Follow（跟随）、Combat（战斗）、Idle。","【跟随优先级】玩家遇敌 → 伙伴进 Combat；无敌人 → Follow。","【测试】玩家打怪，伙伴自动帮忙。","【完成】“好队友”上线！","【注意】别让伙伴和玩家抢一个点（目标偏移，第 257 课）。","【进阶】伙伴指令（跟随/攻击/待命）。"],
   "tips":[{"t":"success","c":"AI 伙伴 = 跟随（状态）+ 战斗（复用敌人逻辑）+ 切换（玩家遇敌转战斗）。"}]},
 ],
 "errors":[{"err":"伙伴挡路/挤玩家？","why":"跟随目标点太近","fix":"加大 followDistance；给目标加偏移；agent 半径配合。"}],
 "exercise":["实现伙伴跟随与保持距离","实现伙伴发现敌人攻击","做跟随/战斗状态切换"],
 "summary":"AI 伙伴完成。下一课寻路章综合练习。"},

{"num":260,"title":"寻路综合练习：AI 追逐与逃脱","summary":"整合寻路章全部能力，做“追逐与逃脱”玩法：AI 追玩家、玩家逃、多 AI 协作。","keywords":"寻路综合,追逐,逃脱,多ai,玩法整合,毕业","time":"约 25 分钟","difficulty":"入门",
 "objectives":["整合寻路全部能力","制作追逐玩法","完成 AI 章毕业"],
 "intro":"寻路章毕业项目：一个“AI 追逐”小玩法——敌人有视野、会追击、会协作，玩家要逃到出口。",
 "sections":[
  {"h":"玩法设计","lead":"追与逃。",
   "steps":["【主题】“逃离实验室”：3 个巡逻敌人，玩家收集 3 把钥匙后逃到出口。","【模块】","① 场景：用 ProBuilder 搭迷宫/走廊（第 231-232 课）。","② NavMesh 烘焙（第 253 课）。","③ 敌人：巡逻+视野+追击（第 256/235 课）。","④ 群组：多敌人分散追击（第 257 课）。","⑤ 钥匙与门（第 238 课）。","⑥ 第一人称控制（第 227 课）。","⑦ 音效/HUD/结束（第 178/247/163 课）。","【节奏】敌人多、巡逻路线交叉，形成压力。","【注意】先搭场景与烘焙，再写 AI，最后联调。"],
   "tips":[{"t":"note","c":"综合玩法 = 场景（能走）+ AI（会追）+ 目标（钥匙/出口）+ 反馈。四层。"}]},
  {"h":"实现与联调","lead":"拼出“紧张感”。",
   "steps":["【场景】迷宫走廊 + 障碍物（NavMeshObstacle 门，第 254 课）。","【烘焙】Bake NavMesh + 调 Agent 参数。","【敌人】3 个敌人：各自路径点巡逻 + 视野发现玩家追击。","【群组】敌人追击目标加偏移，不挤。","【钥匙】3 把钥匙 + 3 扇门（第 238 课钥匙门）。","【出口】到达出口触发胜利（第 163 课）。","【被抓】敌人接触玩家 → 失败画面（第 163 课）。","【HUD】钥匙数、剩余敌人、提示。","【音效】警报/脚步/开门（第 178 课）。","【测试】全流程：躲、找钥匙、开门、逃出、被抓。","【调参】敌人速度（比玩家慢一点才“追得上又逃得掉”）、视野距离。","【完成】寻路章毕业！你的 AI“能追”了。","【注意】反复调“追得上又逃得掉”的平衡。"],
   "tips":[{"t":"note","c":"追逃手感 = 敌人略慢于玩家 + 视野有限 + 迷宫遮挡。设计出“紧张但能逃”。"}]},
 ],
 "errors":[{"err":"敌人追太快玩家必死？","why":"速度差太小","fix":"敌人速度设玩家 0.7-0.8 倍；给玩家冲刺技能（第 249 课体力）。"}],
 "exercise":["完成追逐逃脱玩法","调平衡性","整合全部寻路能力"],
 "summary":"寻路章毕业！下一章进入性能优化。"},

# ============ 第16章 性能优化 (266-280) ============
{"num":261,"title":"性能优化入门与 Profiler","summary":"认识性能优化：Profiler 工具、帧率、瓶颈定位，科学的优化流程。","keywords":"性能优化,profiler,帧率,瓶颈,优化流程,定位问题","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解性能指标","掌握 Profiler","掌握优化流程"],
 "intro":"“卡”是游戏杀手。本课学“先测后优”：用 Profiler 找到瓶颈再优化。",
 "sections":[
  {"h":"性能指标","lead":"看什么数据。",
   "steps":["【帧率 FPS】每秒渲染帧数：60 流畅、30 及格、<30 卡。","【帧时间】每帧耗时（ms）：16.6ms=60fps、33.3ms=30fps。","【瓶颈】最耗时的环节（渲染/物理/脚本/GC）就是瓶颈。","【Draw Call】渲染调用数：越多越卡（第 224 课）。","【GC 分配】垃圾回收分配：每帧分配多→频繁 GC 卡顿。","【内存】占用多少、是否超限。","【目标】移动端 30-60fps、PC 60+、VR 90+。","【优化原则】先测后优、抓大头、用数据说话。","【注意】别凭感觉优化，数据驱动。","【完成】知道“看什么”。","【工具】Profiler 是最重要的性能工具。"],
   "tips":[{"t":"note","c":"性能三指标：帧率（流畅度）、Draw Call（渲染）、GC（卡顿）。先测再优。"}]},
  {"h":"Profiler 使用","lead":"性能“体检仪”。",
   "steps":["【打开】Window → Analysis → Profiler。","【录制】点 Record 录制当前场景性能数据。","【模块】","CPU Usage：每帧各函数耗时（找热点）。","Rendering：Draw Call、三角面数。","Memory：内存占用。","Physics：物理耗时。","Scripts：脚本耗时。","【读法】播放时暂停，看 CPU 里哪一块占满（绿色渲染/紫色物理/蓝色脚本）。","【深入】点某个热点，看调用栈定位到具体函数/对象。","【Deep Profile】（进阶）逐函数剖析（慢但详细）。","【设备 Profile】（进阶）连真机看移动端真实性能。","【实战】运行你的游戏，找最耗时模块。","【完成】会用“体检仪”了！","【注意】Profiler 在编辑器会有点失真，真机更准。"],
   "tips":[{"t":"success","c":"Profiler 读法：录 → 看 CPU 哪块满 → 点热点查栈 → 定位函数/对象 → 优化。"}]},
 ],
 "errors":[{"err":"Profiler 数据看不懂？","why":"模块不熟","fix":"先看 CPU Usage 主时间轴颜色分布；逐个展开模块；查调用栈。"}],
 "exercise":["录制一段游戏性能数据","定位 CPU 最耗时模块","找出一个可优化点"],
 "summary":"性能优化入门完成。下一课学帧率与目标平台。"},

{"num":262,"title":"帧率与目标平台","summary":"管理帧率：目标帧率、垂直同步、自适应帧率，让游戏“稳定流畅”。","keywords":"帧率,targetframerate,垂直同步,vsync,自适应,流畅","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握帧率控制","掌握垂直同步","实现自适应"],
 "intro":"“60 帧稳定”比“偶尔 120”体验好。本课学帧率管理。",
 "sections":[
  {"h":"目标帧率设置","lead":"锁帧还是放帧。",
   "steps":["【设置】Application.targetFrameRate = 60;","【说明】限制最大帧率：省电、稳定、防过热。","【垂直同步】QualitySettings.vSyncCount：0=关、1=60Hz 同步。","【关系】vSyncCount>0 时 targetFrameRate 效果受限。","【PC】开垂直同步避免画面撕裂（60 或 144 看显示器）。","【移动端】vSyncCount=0 + targetFrameRate=60（或 30）最可控。","【高刷屏】高刷屏（120Hz）可设 120（进阶）。","【注意】帧率设置要在游戏启动时（Awake）执行。","【完成】帧率“可控”。","【测试】在 Profiler 看实际帧率。","【推荐】先 60，性能不足降 30。"],
   "tips":[{"t":"note","c":"帧率管理 = targetFrameRate 锁上限 + vSyncCount 控同步。两参数管流畅。"}]},
  {"h":"自适应帧率","lead":"“按设备调”。",
   "steps":["【需求】低配设备自动降画质/帧率。","【检测帧率】每帧统计平均 FPS：","float fps;","void Update() { fps = 1f / Time.deltaTime; }","【检测耗时】或直接看帧时间是否超目标。","【自适应降级】帧率连续低于 30 时：","降低画质（QualitySettings 等级）、关后期、降分辨率。","【实现】","if (fps < 30f && quality > 0) {","quality--;","QualitySettings.SetQualityLevel(quality);","}","【恢复】帧率恢复后逐步提升（防抖动，加延迟）。","【设备分级】首次运行按硬件/分辨率选画质档位（进阶）。","【注意】别频繁切换画质（卡顿感）。","【完成】“聪明”的帧率管理。","【测试】低配模拟下看自动降级。","【进阶】动态分辨率（URP Render Scale）。"],
   "tips":[{"t":"success","c":"自适应 = 测帧率 → 连续低就降画质。高端机全开、低端机保帧。"}]},
 ],
 "errors":[{"err":"锁 60 却跑 30？","why":"垂直同步或设备限制","fix":"确认 vSyncCount=0；targetFrameRate 在 Awake 设置；检查硬件/编辑器限制。"}],
 "exercise":["设置目标帧率与垂直同步","实现自适应降级","对比不同帧率下的体验"],
 "summary":"帧率管理完成。下一课学渲染优化。"},

{"num":263,"title":"渲染优化（合批与光影）","summary":"掌握渲染优化：静态/动态合批、光影烘焙、Shader 精简，降 Draw Call。","keywords":"渲染优化,合批,静态合批,光影烘焙,draw call,shader","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握合批","掌握光影优化","掌握 Shader 精简"],
 "intro":"渲染是 3D 游戏最大开销。本课把 Draw Call 与光影成本降下来。",
 "sections":[
  {"h":"合批技术","lead":"让 GPU 一次画一批。",
   "steps":["【静态合批】静态物体（勾 Static）同材质自动合并：一次渲染调用。","【条件】同材质 + 同 Shader + 静态。","【动态合批】小物体（顶点少）自动合批（Unity 自动，有条件：顶点数限制）。","【SRP Batcher】URP 的合批器：同 Shader 变体材质批量渲染（默认开）。","【GPU Instancing】大量同模型同材质：实例化绘制（草、树）。","【图集】UI/精灵合批（第 203 课）。","【查看】Frame Debugger（Window → Analysis）看 Draw Call 与合批情况。","【优化动作】","统一材质（少换材质）。","同材质物体勾 Static。","用图集/共享贴图。","【目标】手游 Draw Call < 100-200。","【测试】Profiler/Frame Debugger 对比合批前后。","【完成】Draw Call “打下来了”！"],
   "tips":[{"t":"note","c":"合批四法：静态合批、动态合批、SRP Batcher、GPU Instancing。按场景选。"}]},
  {"h":"光影优化","lead":"少算光。",
   "steps":["【烘焙】静态场景光影烘焙（第 192 课）：运行零光照计算。","【灯光数量】实时灯少用（URP 限制 + 性能）。","【阴影】少开/近距阴影（第 192 课 Shadow Distance）。","【反射探针】一个反射探针服务一片区域（别每物一个）。","【后处理】Bloom 等适量（第 195 课）。","【Shader】用 URP 轻量 Shader；少用复杂 Shader。","【材质】减少多 Pass/透明材质。","【LOD】远处低模（第 245 课）。","【综合】“烘焙 + 少灯 + 短阴影”是 3D 场景标配。","【测试】逐项开关对比帧率。","【完成】光影成本“可控”。","【推荐】静态全烘焙、动态只开必要的灯。","【说明】URP 对光照数量有严格限制（Forward 每物体最多 8 实时灯）。"],
   "tips":[{"t":"success","c":"光影优化口诀：静态烘焙、实时灯少、阴影短、后处理轻。四句够用。"}]},
 ],
 "errors":[{"err":"合批没生效？","why":"材质不同或没勾 Static","fix":"统一材质；静态物体勾 Static；用 Frame Debugger 确认合批。"}],
 "exercise":["用 Frame Debugger 分析 Draw Call","做静态合批与图集","烘焙光影降低开销"],
 "summary":"渲染优化完成。下一课学物理优化。"},

{"num":264,"title":"物理优化","summary":"优化物理：减少刚体/碰撞体、固定步长、层过滤，降物理开销。","keywords":"物理优化,刚体数量,固定步长,层过滤,碰撞矩阵,物理性能","time":"约 13 分钟","difficulty":"入门",
 "objectives":["减少物理对象","掌握层过滤","掌握物理设置"],
 "intro":"“成百上千刚体”是物理卡顿元凶。本课把物理开销压下来。",
 "sections":[
  {"h":"减少物理计算","lead":"少算碰撞。",
   "steps":["【刚体数量】刚体/碰撞体越多物理越慢：能用触发器的别用刚体碰撞。","【静态物】静止的物体用 Static（不带 Rigidbody，碰撞体即可）。","【合并碰撞】相邻静态物用复合碰撞体（Composite Collider）合并。","【远距离】远处物体停物理（Sleep）或 Cull。","【碰撞检测】低速物用 Discrete、高速才 Continuous（省计算）。","【休眠】静态刚体自然休眠（不再算）；别每帧唤醒。","【触发器】触发器数量控制（同时活跃的触发器多了也贵）。","【对象池】高频物理物用对象池（第 198 课）。","【测试】场景放 1000 个刚体与 100 个对比帧率。","【完成】物理“轻”了！"],
   "tips":[{"t":"note","c":"物理瘦身：少刚体、合并碰撞、静态不带刚体、触发器适量。四条。"}]},
  {"h":"层过滤与固定步长","lead":"不该撞的别算。",
   "steps":["【层过滤】Edit → Project Settings → Physics → Layer Collision Matrix：","勾选“哪些层互相碰撞”：子弹不撞子弹、敌人不撞敌人。","【好处】物理系统跳过不碰撞的层对，省大量计算。","【固定步长】Fixed Timestep：物理更新间隔（默认 0.02=50Hz）。","调大（0.03）降物理精度省性能；调小更精确更耗。","【物理脚本】FixedUpdate 里逻辑别太重（每物理帧跑）。","【力】AddForce 用 Impulse（一次性）比持续 Force 省。","【Rigidbody2D/3D】2D 物理与 3D 物理互相独立、各自开销。","【测试】设层矩阵后对比帧率。","【注意】层矩阵改错会导致“穿模”（记得测试）。","【完成】物理“精准省电”。","【推荐】项目一开始就配好层矩阵。","【进阶】物理查询（Raycast）也按层过滤。"],
   "tips":[{"t":"success","c":"物理优化两招：层矩阵（跳过无关碰撞）+ 固定步长（控精度换性能）。"}]},
 ],
 "errors":[{"err":"物体穿模了？","why":"层矩阵误关或 Fixed Timestep 太大","fix":"检查层矩阵是否禁用了必要碰撞；恢复 Fixed Timestep 0.02。"}],
 "exercise":["配层碰撞矩阵","合并静态碰撞体","调 Fixed Timestep 对比"],
 "summary":"物理优化完成。下一课学脚本与 GC 优化。"},

{"num":265,"title":"脚本与 GC 优化","summary":"优化脚本：缓存引用、避免每帧分配、协程与字符串，消灭 GC 卡顿。","keywords":"gc优化,垃圾回收,缓存,字符串拼接,协程,分配","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握缓存技巧","避免每帧分配","优化字符串"],
 "intro":"“GC 卡顿”是脚本元凶。本课学会写出“不产生垃圾”的代码。",
 "sections":[
  {"h":"缓存与查找优化","lead":"别每帧“找”。",
   "steps":["【问题】GetComponent/Find/FindObjectOfType 每帧调用很慢。","【缓存】在 Awake/Start 缓存引用：","private Rigidbody rb;","void Awake() { rb = GetComponent<Rigidbody>(); }","【之后】直接用 rb，不再 GetComponent。","【Find 禁用】避免 FindGameObjectWithTag/Find（用引用/单例/序列化）。","【transform 缓存】transform 属性访问有开销，缓存：","Transform t; void Awake() { t = transform; }","【循环】for 比 foreach 快（foreach 有枚举器分配）。","【每帧循环】Update 里别放重复查找。","【注意】改对象结构后缓存会失效（重新获取）。","【测试】Profiler 对比缓存前后。","【完成】脚本“轻”了！"],
   "tips":[{"t":"note","c":"缓存黄金律：Awake 拿一次引用，Update 直接复用。GetComponent 进 Start 不进 Update。"}]},
  {"h":"GC 优化与字符串","lead":"消灭垃圾。",
   "steps":["【GC 原理】每帧分配（new）的对象最终要回收（GC），回收时卡顿。","【避免每帧分配】","每帧 new 数组/List/string = 垃圾。","复用：预分配 List/数组，Clear 后重用。","【字符串拼接】每帧 “分数：” + score 会产生新字符串：","用 StringBuilder（System.Text）：","StringBuilder sb = new StringBuilder(16);","sb.Clear(); sb.Append(\"分数：\").Append(score); text.text = sb.ToString();","或缓存：“只在分数变化时更新文字”。","【闭包/委托】每帧 new 委托也是垃圾：缓存委托。","【协程】每帧启动协程有开销：常驻协程用 while(true) + yield。","【对象池】高频物对象池（第 198 课）。","【Profiler】Memory 模块看 GC Alloc 每帧分配量。","【目标】移动端每帧 GC Alloc < 1KB 理想。","【注意】装箱（int 转 object）也分配：避免隐式装箱。","【完成】“零垃圾”代码！","【测试】Profiler 看 GC Alloc 下降。","【说明】减少分配 = 减少 GC 卡顿，这是脚本优化核心。"],
   "tips":[{"t":"success","c":"GC 三不：不每帧 new、不每帧拼字符串、不每帧 GetComponent。做到就流畅。"}]},
 ],
 "errors":[{"err":"还是卡？","why":"GC Alloc 仍高","fix":"用 Profiler Memory 定位分配源；重点查每帧 new/字符串/委托。"}],
 "exercise":["缓存组件引用","用 StringBuilder 优化拼接","用 Profiler 验证 GC 下降"],
 "summary":"脚本与 GC 优化完成。下一课学资源与加载优化。"},

{"num":266,"title":"资源与加载优化","summary":"优化资源：纹理压缩、音频压缩、模型优化、Resources 管理，瘦身不减质。","keywords":"资源优化,纹理压缩,音频压缩,模型,加载,resources","time":"约 14 分钟","difficulty":"入门",
 "objectives":["优化纹理与音频","优化模型","掌握加载方式"],
 "intro":"“包太大”“加载慢”是资源问题。本课学资源“瘦身”。",
 "sections":[
  {"h":"纹理与音频优化","lead":"最占体积的两种。",
   "steps":["【纹理】贴图是体积大户：","尺寸 2 的幂、尽量 1024 以下（UI/小物 256-512）。","Compression 选 ASTC（安卓）/ASTC+（iOS）等平台格式。","Mipmap：需要远景的 3D 贴图开；UI/特效关（省内存）。","Max Size 限制：按用途裁剪最大尺寸。","【音频】","短音效用 Decompress On Load（即时）；长 BGM 用 Streaming（流式，省内存）。","压缩格式（Vorbis/MP3）体积小。","采样率 44.1k 够用，别用 96k。","【模型】","Mesh Compression 压缩；顶点/骨骼精简（美术侧）。","【图集】UI/精灵图集（第 203 课）。","【检查】Project 里按 Size 排序找大资产。","【完成】资源“瘦身”。","【测试】打包体积对比。","【推荐】发布前统一走一遍资源检查。","【注意】压缩过度会糊/有声损，按平台平衡。"],
   "tips":[{"t":"note","c":"资源瘦身：纹理压格式、音频选流式、模型压网格。三招降体积。"}]},
  {"h":"加载方式优化","lead":"别“一把梭”。",
   "steps":["【Resources 文件夹】拖进去的都会打进包：别乱放。","【Resources.Load】运行时从 Resources 加载：","GameObject obj = Resources.Load<GameObject>(\"Prefabs/Cube\");","Instantiate(obj);","【问题】Resources 里的都进包：用 AssetsBundle/Addressables 更省。","【Addressables】官方资源管理：按需下载/加载，推荐（进阶）。","【场景异步】SceneManager.LoadSceneAsync 异步加载不卡（第 269 课）。","【延迟加载】远距资源到达才加载（LOD 思维）。","【卸载】Resources.UnloadUnusedAssets() 清理（少调）。","【AssetBundle】自定义分包（进阶）。","【选择】小项目用 Resources 简单够；大项目上 Addressables。","【完成】加载“按需”了！","【测试】对比包大小与加载时间。","【注意】Resources.Load 的路径是“相对 Resources”的路径。","【推荐】进阶必学 Addressables（进阶教程另行）。"],
   "tips":[{"t":"success","c":"加载优化 = 资源分类（按需加载）+ 异步（不卡帧）+ 不滥用 Resources。三招。"}]},
 ],
 "errors":[{"err":"Resources.Load 返回 null？","why":"路径错或资源没放 Resources 文件夹","fix":"确认资源在 Resources 目录下；路径写对（不含 Resources 前缀）。"}],
 "exercise":["压缩纹理并对比体积","设置音频加载方式","用 Resources.Load 按需加载"],
 "summary":"资源优化完成。下一课学内存管理。"},

{"num":267,"title":"内存管理","summary":"掌握内存：内存监控、卸载、资源生命周期，控制游戏内存占用。","keywords":"内存管理,内存监控,卸载,生命周期,profiler,内存占用","time":"约 13 分钟","difficulty":"入门",
 "objectives":["监控内存","掌握卸载时机","控制内存峰值"],
 "intro":"“内存爆了闪退”是移动端大敌。本课学监控与回收内存。",
 "sections":[
  {"h":"内存监控","lead":"看用了多少。",
   "steps":["【Profiler Memory】Window → Analysis → Profiler → Memory 模块。","【看数据】Total Allocated（已分配）、Texture/Audio 占比、GC 堆大小。","【模块分类】看哪类资源占内存大头（纹理/音频/网格/动画）。","【运行时监控】GameObject 内存监控：","Debug.Log(System.GC.GetTotalMemory(false)); // GC 堆","【真实设备】真机看任务管理器/系统内存（进阶）。","【内存分布】","资源内存（纹理/音频/模型）。","运行时分配（对象、GC 堆）。","【目标】移动端 < 1-2GB（看设备）、PC 宽松。","【完成】“看得到”内存了！"],
   "tips":[{"t":"note","c":"内存监控：Profiler Memory 看资源、System.GC 看堆。两项都盯。"}]},
  {"h":"回收与生命周期","lead":"“该删就删”。",
   "steps":["【Destroy】不用的大对象 Destroy 掉。","【场景卸载】切场景后旧场景资源被卸载（除非 DontDestroyOnLoad）。","【Resources.UnloadUnusedAssets()】卸载无引用的资源（协程调用，避免主线程卡）：","StartCoroutine(UnloadCoroutine());","IEnumerator UnloadCoroutine() {","yield return new WaitForSeconds(5f);","Resources.UnloadUnusedAssets();","yield return null;","}","【注意】别频繁调用（有开销）。","【对象池】复用代替销毁（减少分配，第 198 课）。","【纹理卸载】大图不用时卸载（按场景/区域）。","【音频】长音频用 Streaming 后不占内存（第 266 课）。","【地址化】Addressables 按需加载/释放（进阶）。","【泄漏】DontDestroyOnLoad 的对象不会自动卸载：跨场景管理器用单例+小心。","【完成】内存“进出有度”。","【测试】长时间游玩后看内存是否稳定（无泄漏）。","【注意】真机长时间游玩是内存测试关键。","【常见坑】贴图集未压缩、动画不卸载、场景大资源常驻。"],
   "tips":[{"t":"success","c":"内存管理 = 监控 + 按需卸载 + 对象池复用 + 防泄漏。四板斧。"}]},
 ],
 "errors":[{"err":"内存一直涨不回落？","why":"资源泄漏或没卸载","fix":"检查 DontDestroyOnLoad 常驻对象；卸载无用资源；用 Profiler 定位泄漏源。"}],
 "exercise":["用 Profiler 监控内存","实现按需卸载","长时间游玩验证内存稳定"],
 "summary":"内存管理完成。下一课学场景加载优化。"},

{"num":268,"title":"场景加载优化（异步）","summary":"用异步加载场景：Loading 界面、进度条、加载提示，切场景不卡顿。","keywords":"场景加载,异步,async,loading界面,进度条,loadsceneasync","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现异步加载","实现进度条","实现 Loading 界面"],
 "intro":"“切场景白屏几秒”体验差。本课用异步加载+进度条让切换“顺滑”。",
 "sections":[
  {"h":"异步加载基础","lead":"LoadSceneAsync。",
   "steps":["【同步问题】SceneManager.LoadScene 会卡主线程（大场景几秒白屏）。","【异步加载】SceneManager.LoadSceneAsync(“”Level2“”);","返回 AsyncOperation，后台加载不阻塞。","【基础用法】","AsyncOperation op = SceneManager.LoadSceneAsync(“”Level2“”);","【进度】op.progress（0-0.9 实际加载，0.9-1 是激活）。","【激活】op.allowSceneActivation = false：加载完不自动切，等我们手动。","【完整】“加载完→手动激活→切场景”。","【注意】异步加载中场景还没切换，别放玩家乱走。","【完成】异步“通了”！"],
   "tips":[{"t":"note","c":"异步加载 = LoadSceneAsync + allowSceneActivation 控制 + 完成手动激活。三步。"}]},
  {"h":"Loading 界面与进度条","lead":"“转圈圈”给反馈。",
   "steps":["【Loading 界面】Canvas：进度条（Slider/Image Filled）+ 提示文字。","【脚本 LoadManager】","public Slider progressBar;","public TMP_Text tipText;","public void LoadLevel(string sceneName) {","StartCoroutine(LoadAsync(sceneName));","}","IEnumerator LoadAsync(string sceneName) {","gameObject.SetActive(true); // 显示 Loading","AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);","op.allowSceneActivation = false;","while (!op.isDone) {","float p = Mathf.Clamp01(op.progress / 0.9f);","progressBar.value = p;","// 可随机换加载提示","yield return null;","}","op.allowSceneActivation = true; // 切场景","}","【说明】progress 除以 0.9 映射到 0-1（因为 0.9 后是激活）。","【过渡动画】Loading 界面淡入淡出（第 159 课）。","【调用】到关卡入口：LoadManager.Instance.LoadLevel(“”Level2“”);","【完成】切场景“丝滑”！","【注意】Loading 界面要在“新场景”之外（DontDestroyOnLoad 或先显示）。","【进阶】场景预加载（提前 LoadSceneAsync 后台预载，进阶）。"],
   "tips":[{"t":"success","c":"Loading 三件套：显示面板 + 进度条（progress/0.9）+ 完成激活。切场景零卡顿。"}]},
 ],
 "errors":[{"err":"进度条到 90% 停住？","why":"allowSceneActivation=false 且没设 true","fix":"进度 1 后设置 op.allowSceneActivation = true 激活场景。"}],
 "exercise":["实现异步加载场景","做 Loading 界面与进度条","实现“继续”按钮激活"],
 "summary":"场景加载优化完成。下一课做对象池实战。"},

{"num":269,"title":"对象池实战（完整系统）","summary":"做一个通用对象池系统：任意类型复用、自动扩容、场景管理，一劳永逸。","keywords":"对象池实战,通用对象池,复用,自动扩容,池系统","time":"约 15 分钟","difficulty":"入门",
 "objectives":["实现通用对象池","实现自动扩容","接入游戏场景"],
 "intro":"第 198/215 课用了简单对象池，本课做一个“通用、可复用的对象池系统”。",
 "sections":[
  {"h":"通用对象池设计","lead":"一个池管所有。",
   "steps":["【设计】用 Dictionary 按预制体分池：","public class ObjectPool : MonoBehaviour {","public static ObjectPool Instance;","private Dictionary<string, Queue<GameObject>> pools = new Dictionary<string, Queue<GameObject>>();","void Awake() { Instance = this; }","public GameObject Get(GameObject prefab, Vector3 pos, Quaternion rot) {","string key = prefab.name;","GameObject obj;","if (pools.ContainsKey(key) && pools[key].Count > 0) {","obj = pools[key].Dequeue();","obj.transform.position = pos;","obj.transform.rotation = rot;","obj.SetActive(true);","} else {","obj = Instantiate(prefab, pos, rot);","}","return obj;","}","public void Release(GameObject obj, float delay = 0f) {","if (delay <= 0f) { obj.SetActive(false); PoolIt(obj); }","else StartCoroutine(ReleaseLater(obj, delay));","}","IEnumerator ReleaseLater(GameObject obj, float d) { yield return new WaitForSeconds(d); obj.SetActive(false); PoolIt(obj); }","void PoolIt(GameObject obj) {","string key = obj.name.Replace(“”(Clone)“", "”“”);","if (!pools.ContainsKey(key)) pools[key] = new Queue<GameObject>();","pools[key].Enqueue(obj);","}","}","【自动扩容】池空时自动 Instantiate（else 分支）。","【注意】Release 时先 SetActive(false) 再入池。","【完成】通用池“上线”！"],
   "tips":[{"t":"note","c":"通用对象池 = Dictionary 分池 + Get 复用/新建 + Release 回收。一套管所有。"}]},
  {"h":"接入实战","lead":"子弹、特效、敌人全走池。",
   "steps":["【子弹】发射时：","GameObject b = ObjectPool.Instance.Get(bulletPrefab, firePoint.position, firePoint.rotation);","b.GetComponent<Bullet>().Init(dir);","命中/超时：ObjectPool.Instance.Release(b);","【特效】爆炸：Get(explosionPrefab, pos, rot) → 播放 → Release(explosion, 2f)（延时回收）。","【敌人】死亡：Get(死亡特效) + Release(敌人)。","【Init 重置】复用对象要重置状态：子弹 Init 重置速度/伤害；敌人重置 hp。","【场景切换】池对象跨场景会丢：DontDestroyOnLoad 挂 ObjectPool 或场景内重建（第 172 课）。","【调试】Profiler 看 GC Alloc 是否大幅下降。","【完成】游戏“零 GC”体验！","【注意】入池对象要复位（位置/旋转/active/组件状态）。","【推荐】所有高频物（子弹/粒子/敌人/飘字）一律对象池。"],
   "tips":[{"t":"success","c":"对象池接入 = Get（取）+ 初始化（重置）+ Release（还）。三行养成习惯。"}]},
 ],
 "errors":[{"err":"池化对象状态残留？","why":"没重置","fix":"Get 时统一 Reset（位置/速度/hp/特效 Clear）；Release 前也清状态。"}],
 "exercise":["实现通用对象池系统","子弹/特效全走池","验证 GC 大幅下降"],
 "summary":"对象池系统完成。下一课做 LOD 与遮挡剔除实战。"},

{"num":270,"title":"LOD 与遮挡剔除实战","summary":"把 LOD 与遮挡剔除落实到项目：场景优化实战、工具使用、验证效果。","keywords":"lod实战,遮挡剔除实战,场景优化,验证,性能提升","time":"约 14 分钟","difficulty":"入门",
 "objectives":["落地 LOD","落地遮挡剔除","验证优化效果"],
 "intro":"第 245 课讲了原理，本课动手把两者落地到真实场景并量化验证。",
 "sections":[
  {"h":"LOD 落地","lead":"给大场景装 LOD。",
   "steps":["【准备】场景里的大物体（建筑、树、山体）需要多精度模型（美术提供或商店）。","【添加】选中物体 → Add Component → LOD Group。","【配置】LOD 0（最高模）、LOD 1（中模）、LOD 2（低模）、Culled。","【拖模型】每级把对应 Renderer 拖入。","【距离】默认比例（如 0.6/0.3/0.1），按场景大小调整。","【预览】Scene 视图 Camera 模式看各级切换效果。","【低模来源】可用 Blender 减面/商店 LOD 包；或手动简化（进阶）。","【静态物体】LOD 配合 Static 效果更好。","【验证】Profiler 看三角面数（Triangles）明显下降。","【完成】LOD“落地”！","【注意】移动端 LOD 更要积极（低模切换更早）。"],
   "tips":[{"t":"note","c":"LOD 落地 = LOD Group 组件 + 三级模型 + 距离配置。三角面数立降。"}]},
  {"h":"遮挡剔除落地","lead":"让看不见的不渲染。",
   "steps":["【准备】把场景静态物体（墙、建筑、地形）勾 Static（含 Occluder）。","【窗口】Window → Rendering → Occlusion Culling。","【Bake】点 Bake（等进度条完成）。","【检查】Scene 视图选 Occlusion Culling 模式：","蓝色=遮挡体、绿色=被遮挡物、黄色=动态物。","【验证】播放后移动相机，用 Profiler/Stats 看 Draw Call 变化。","【常见问题】烘焙后闪烁 → 改场景重新 Bake。","【动态物】角色/敌人是动态物：被静态遮挡剔除（也受益）。","【性能】遮挡烘焙有内存开销：场景大分区域烘焙（进阶）。","【完成】遮挡剔除“落地”！","【测试】站在墙后，看墙后 Draw Call 是否为 0。","【注意】只用实心大物体做遮挡体（墙），别用透明/小物。"],
   "tips":[{"t":"success","c":"遮挡剔除落地 = 静态勾选 + Bake + 验证。室内场景 Draw Call 立降。"}]},
 ],
 "errors":[{"err":"遮挡烘焙后画面闪烁？","why":"烘焙数据过期或遮挡体设置错","fix":"改场景后重新 Bake；用实心大物体做遮挡体；检查 Static 勾选。"}],
 "exercise":["给大物体配 3 级 LOD","烘焙遮挡剔除","量化对比优化前后性能"],
 "summary":"LOD 与遮挡剔除实战完成。下一课学移动端优化。"},

{"num":271,"title":"移动端性能优化","summary":"针对移动端优化：设备限制、发热控制、画质分级、电池友好。","keywords":"移动端优化,设备限制,发热,画质分级,电池,android","time":"约 14 分钟","difficulty":"入门",
 "objectives":["了解设备限制","掌握画质分级","控制发热"],
 "intro":"“手机”设备五花八门。本课针对移动端做专项优化。",
 "sections":[
  {"h":"移动端限制","lead":"“小屏幕大限制”。",
   "steps":["【设备差异】从低端安卓到高端 iPhone 性能差 5-10 倍。","【限制】发热降频、内存小、续航、无独显。","【目标】低端保 30fps、中端 60、高端全开。","【GPU 限制】Draw Call/粒子/后处理都要克制。","【内存】安卓可用内存小：纹理压缩、资源精简（第 266-267 课）。","【存储】包体尽量 < 500MB（渠道限制）。","【发热】长时间全开会发热降频卡顿。","【测试】真机多档位测试（别只在高端机测）。","【完成】“知道敌人”。","【设备分级】按 GPU 型号/内存分级（进阶）。"],
   "tips":[{"t":"note","c":"移动端三限制：性能（设备差异）、内存（小）、发热（降频）。都避开才能稳。"}]},
  {"h":"画质分级与节能","lead":"“按设备开特效”。",
   "steps":["【画质分级】QualitySettings 定义多档（Low/Medium/High/Ultra）。","【档位差异】","Low：关后处理、无阴影/低阴影、低分辨率、关粒子。","Medium：简单后处理、软阴影低。","High：Bloom、高阴影、特效全开。","【启动选档】首次运行按设备：","if (SystemInfo.graphicsMemorySize > 2000) QualitySettings.SetQualityLevel(3); else ...","【动态调整】帧率低自动降档（第 262 课）。","【节能】targetFrameRate=30 低档省电；空闲暂停渲染（进阶）。","【电池】屏幕亮度/粒子/后处理影响电量。","【按场景】菜单低档、关卡高档（进阶）。","【测试】每档位真机验证帧率与发热。","【完成】“会分级”的移动端。","【推荐】发布至少 3 档画质。"],
   "tips":[{"t":"success","c":"移动端画质 = 多档 QualitySettings + 启动按设备选档 + 动态降档。三级保障。"}]},
 ],
 "errors":[{"err":"高端机也卡？","why":"没分级或优化没做","fix":"先做资源/渲染/GC 基础优化（第 263-267 课）；再分级；真机验证。"}],
 "exercise":["配置多档画质","启动按设备选档","真机验证帧率与发热"],
 "summary":"移动端优化完成。下一课做性能分析实战。"},

{"num":272,"title":"性能分析实战（综合排障）","summary":"用 Profiler 实战排障：定位卡顿根因、逐个优化、复测验证的完整流程。","keywords":"性能分析,排障,定位根因,优化流程,profiler实战,卡顿排查","time":"约 16 分钟","difficulty":"入门",
 "objectives":["掌握排查流程","实战定位瓶颈","完成优化闭环"],
 "intro":"“卡”了怎么查？本课走一遍完整排障流程：录数据→定位→优化→复测。",
 "sections":[
  {"h":"排障流程","lead":"五步定位。",
   "steps":["【第一步 复现】稳定复现卡顿场景（别“偶尔卡”找不到）。","【第二步 录制】Profiler 录制卡顿时段。","【第三步 定位】看 CPU 时间轴哪块爆满（渲染/物理/脚本/GC）。","【第四步 深入】点热点 → 调用栈 → 定位到具体函数/对象/资源。","【第五步 优化】针对性优化（查对应章节）。","【复测】优化后再录，对比帧时间与分配。","【分类排查】","渲染卡：看 Draw Call/三角面 → 合批/烘焙/LOD。","物理卡：看 Physics → 刚体/碰撞/层。","脚本卡：看 Scripts → 缓存/循环/每帧逻辑。","GC 卡：看 GC Alloc → 分配源。","【记录】每次优化记录数据（优化前/后）。","【完成】“会排障”了！"],
   "tips":[{"t":"note","c":"排障五步：复现→录制→定位→优化→复测。数据说话，不靠猜。"}]},
  {"h":"典型案例实战","lead":"看两个“病人”。",
   "steps":["【案例1 物理卡顿】","症状：物体多时掉帧。","Profiler：Physics 占满。","排查：刚体数量多、动态碰撞频繁。","优化：静态物去刚体、合并碰撞、层过滤（第 264 课）。","复测：Physics 耗时下降。","【案例2 GC 卡顿】","症状：周期性卡一下。","Profiler：GC Alloc 峰值高。","排查：字符串拼接/每帧 new。","优化：StringBuilder/缓存/对象池（第 265 课）。","复测：GC Alloc 平缓。","【通用】帧率不稳多为“分配”或“加载”；持续低帧多为“渲染/物理”。","【工具组合】Profiler + Frame Debugger + Stats 窗口（Game 视图 Stats）。","【真机】编辑器优化完，真机再验证（环境更真实）。","【完成】“医生”养成！","【注意】一次改一个变量，避免“改多了不知道谁生效”。"],
   "tips":[{"t":"success","c":"优化纪律：一次只改一个、每次都要复测。改多了=白改。"}]},
 ],
 "errors":[{"err":"优化后没提升？","why":"改错点或没复测","fix":"确认改的是瓶颈（不是猜测）；复测对比数据；一次改一个变量。"}],
 "exercise":["录制并定位一个真实卡顿","针对性优化并复测","记录优化前后数据"],
 "summary":"性能分析实战完成。下一课优化综合练习。"},

{"num":273,"title":"优化综合练习：性能达标","summary":"综合性能章全部能力，给一个“卡”项目做全面优化，达到目标帧率。","keywords":"优化综合,性能达标,全面优化,目标帧率,综合练习","time":"约 25 分钟","difficulty":"入门",
 "objectives":["全面性能体检","实施综合优化","达成目标帧率"],
 "intro":"性能章毕业项目：拿一个“卡成 PPT”的场景，用全部优化手段做到 60 帧。",
 "sections":[
  {"h":"全面体检","lead":"先“检查”再“开药”。",
   "steps":["【目标】目标平台 60fps（或 30）。","【准备】拿一个性能差的 3D 场景（大量物体/粒子/动态物）。","【体检清单】","① Profiler：CPU 各模块占比。","② Frame Debugger：Draw Call 数。","③ 内存：Profiler Memory。","④ GC Alloc：每帧分配。","⑤ 物理：刚体/碰撞数量。","⑥ 资源：纹理/音频/模型大小。","【记录】写下基线数据（帧率/Draw Call/GC）。","【排序】按“影响大且好改”排序优化项。","【完成】体检报告出炉。","【注意】记录基线才能对比效果。"],
   "tips":[{"t":"note","c":"优化项目 = 体检（记录基线）→ 按影响排序 → 逐项优化 → 复测。工程化。"}]},
  {"h":"实施与复测","lead":"把数据“打下来”。",
   "steps":["【第一优先】Draw Call：图集/合批/静态（第 263 课）。","【第二】GC：对象池/字符串/缓存（第 265/269 课）。","【第三】物理：刚体/层/步长（第 264 课）。","【第四】渲染：烘焙/LOD/遮挡（第 270 课）。","【第五】资源：压缩/流式（第 266 课）。","【每步复测】每优化一项就录一次数据对比。","【达标】达到目标帧率（60 稳定）即完成；未达标继续。","【降级兜底】实在不达标：降画质档/目标 30（第 271 课）。","【记录】输出“优化前后对比表”。","【完成】性能达标！","【注意】一次一项、数据说话。","【交付】总结哪些手段最有效（沉淀经验）。"],
   "tips":[{"t":"success","c":"优化顺序：Draw Call → GC → 物理 → 渲染 → 资源。按性价比排队。"}]},
 ],
 "errors":[{"err":"优化后仍不达标？","why":"瓶颈没抓对或平台限制","fix":"重新 Profiler 定位新瓶颈；降低目标（30fps）；或减少内容量。"}],
 "exercise":["做性能体检并记录基线","按优先级综合优化","达成目标帧率并复测"],
 "summary":"性能优化毕业！下一课学项目架构与规范。"},

{"num":274,"title":"项目架构（单例/事件/对象池）","summary":"搭建可维护项目架构：单例管理、事件系统、数据驱动，让项目“不烂尾”。","keywords":"项目架构,单例,事件系统,数据驱动,可维护,架构设计","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握架构思想","实现事件系统","实现管理器模式"],
 "intro":"“项目一大了就乱”——架构是“不乱”的关键。本课搭一套可扩展架构。",
 "sections":[
  {"h":"架构思想","lead":"分层与职责。",
   "steps":["【分层】游戏代码分层：","管理层（GameManager/AudioManager/UIManager）","数据层（SaveSystem/PlayerStats/Config）","逻辑层（角色/敌人/技能组件）","表现层（动画/特效/UI 表现）","【职责单一】每个脚本只干一件事（PlayerStats 管数值、PlayerMove 管移动）。","【通信】管理层用单例、对象间用事件、配置用数据。","【单例】全局唯一管理器（第 86 课）：GameManager/AudioManager/UIManager。","【事件】解耦对象通信（第 167 课）。","【数据驱动】配置用 ScriptableObject/JSON（第 85 课）。","【好处】改一处不影响全局、新功能易加、别人易看懂。","【注意】别“上帝脚本”（一个脚本管所有）。","【完成】架构思想“有了”。","【推荐】小项目也按“管理/逻辑/表现”分层。"],
   "tips":[{"t":"note","c":"架构三原则：分层（管理/逻辑/表现）、单一职责、解耦（事件/数据）。"}]},
  {"h":"事件系统实现","lead":"“谁出事通知谁”。",
   "steps":["【简单事件】每个系统自己声明事件（第 167 课）：","public event System.Action<int> OnScoreChanged;","【全局事件系统】跨系统解耦：","public static class GameEvents {","public static event System.Action<int> OnScoreChanged;","public static event System.Action OnPlayerDied;","public static void ScoreChanged(int s) => OnScoreChanged?.Invoke(s);","public static void PlayerDied() => OnPlayerDied?.Invoke();","}","【发布】加金币：GameEvents.ScoreChanged(newScore);","【订阅】UI：GameEvents.OnScoreChanged += UpdateScore;","【取消订阅】OnDestroy 时 -=（防泄漏，重要！）。","【好处】金币系统不需要“知道”UI 存在（解耦）。","【注意】订阅不取消 = 内存泄漏（重要坑）。","【实战】把项目的分数/死亡通知改用事件。","【完成】事件系统“通了”。","【进阶】UnityEvent/委托参数化（进阶）。"],
   "tips":[{"t":"danger","c":"订阅事件必须 OnDestroy 取消订阅（-=），否则对象销毁后仍被调用=泄漏/报错。"}]},
 ],
 "errors":[{"err":"事件重复触发？","why":"重复订阅没取消","fix":"订阅时先 -= 再 +=（防重复）；OnDestroy 统一 -=。"}],
 "exercise":["用单例管理核心系统","实现全局事件系统","重构一个模块用事件解耦"],
 "summary":"项目架构完成。下一课做代码规范。"},

{"num":275,"title":"代码规范与项目管理","summary":"掌握代码规范：命名、注释、文件组织、版本控制，写出“专业代码”。","keywords":"代码规范,命名,注释,文件组织,版本控制,git","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握命名规范","掌握文件组织","掌握版本控制"],
 "intro":"“代码要能给别人看、给三个月后的自己看”。本课建立专业规范。",
 "sections":[
  {"h":"命名与注释规范","lead":"“看得懂”的代码。",
   "steps":["【变量】驼峰命名：playerHealth、moveSpeed；私有加下划线 _rb、_hp。","【方法】动词开头：Move()、TakeDamage()、LoadLevel()。","【类】大驼峰：PlayerController、GameManager。","【常量】全大写：MAX_HP。","【Unity 特殊】序列化字段 public 或 [SerializeField] private；事件用 On 开头：OnPlayerDied。","【命名意义】别用 a、b、temp 当变量名；用有意义的：enemyHp。","【注释】关键逻辑写“为什么”（别写“做了什么”）：","// 用局部变量捕获循环变量，避免闭包问题","【注释时机】复杂算法、边界情况、非直觉逻辑。","【中文/英文】团队统一；教程项目中文注释易读。","【一致性】全项目一个风格（对照已有代码）。","【完成】代码“规范”了！","【推荐】写代码时当“要被同事审查”。"],
   "tips":[{"t":"note","c":"规范三问：名字有意义吗？注释讲原因吗？风格统一吗？"}]},
  {"h":"文件组织与版本控制","lead":"“不乱”的项目。",
   "steps":["【文件夹规范】（第 4 章深化）：","Assets/Scripts/（Player/Enemy/UI/Managers 子目录）","Assets/Prefabs/","Assets/Scenes/","Assets/Art/（Textures/Materials/Models）","Assets/Audio/","Assets/Resources/（如用）","【命名文件】与内容一致：PlayerController.cs、Level1.unity。","【Prefab 命名】统一后缀：Enemy_Patrol.prefab、UI_HpBar.prefab。","【场景命名】Level1、MainMenu、GameOver。","【Git 版本控制】","安装 Git → 项目目录 git init。","【.gitignore】Unity 项目忽略：Library/、Temp/、Obj/、Logs/。","【提交】小步提交：做完一个功能 commit 一次，写清 message。","【回滚】出错 git revert/checkout 恢复。","【分支】（进阶）main/develop/feature 分支。","【完成】项目“井井有条”。","【推荐】当天工作当天 commit。","【注意】别把整个项目放云盘当版本控制（Git 才是）。","【工具】GitHub Desktop/Sourcetree 可视化操作。"],
   "tips":[{"t":"success","c":"项目管理 = 文件夹规范 + 命名规范 + Git 小步提交。三件套防“烂尾”。"}]},
 ],
 "errors":[{"err":"Git 提交了一堆垃圾文件？","why":"没配 .gitignore","fix":"添加 Unity .gitignore（Library/Temp 等），清除已提交的垃圾。"}],
 "exercise":["规范命名与注释","整理文件夹结构","初始化 Git 并首次提交"],
 "summary":"代码规范完成！下一课继续进阶修炼与发布。"},
]
